  "md": "С вышки бросили камень в горизонтальном направлении. Через промежуток времени $t = 2$ с камень упал на землю на расстоянии $s = 40$ м от основания вышки. Определить начальную $v_0$ и конечную $v$ скорости камня.",
  "figs": [],
