  "md": "К пружинным весам подвешен блок. Через блок перекинут шнур, к концам которого привязали грузы массами $m_1 = 1{,}5$ кг и $m_2 = 3$ кг. Каково будет показание весов во время движения грузов? Массой блока и шнура пренебречь.",
