  "md": "Вертолёт массой $m = 3{,}5$ т с ротором, диаметр $d$ которого равен 18 м, «висит» в воздухе. С какой скоростью $v$ ротор отбрасывает вертикально вниз струю воздуха? Диаметр струи считать равным диаметру ротора.",
