  "md": "Неподвижная труба площадью поперечного сечения $S$, равной 10 см², изогнута под углом $\\varphi = 90°$ и прикреплена к стене (рис. 2.10). По трубе течёт вода, объёмный расход $Q_V$ которой 50 л/с. Найти силу $F$ давления струи воды, вызванную изгибом трубы.",
