  "parTitle": "§ 2. Динамика материальной точки и тела, движущихся поступательно",
  "topic": "Второй закон Ньютона",
  "page": "41–42",
  "star": false,
  "md": "⁷⁾ Катер массой $m = 2$ т с двигателем мощностью $N = 50$ кВт развивает максимальную скорость $v_{\\max} = 25$ м/с. Определить время $t$, в течение которого катер\nпосле выключения двигателя потеряет половину своей скорости. Принять, что сила сопротивления движению катера изменяется пропорционально квадрату скорости.\n\n> ⁷⁾ Перед решением задач 2.27–2.30 следует предварительно разобрать пример 3 из § 2.",
  "figs": [],
  "first": "⁷⁾ Катер массой m = 2 т с двигателем мощностью N = 50 кВт развивает максимальную скорость v = 25 м/с.",
