  "md": "Начальная скорость $v_0$ пули равна 800 м/с. При движении в воздухе за время $t = 0{,}8$ с её скорость уменьшилась до $v = 200$ м/с. Масса $m$ пули равна 10 г. Считая силу сопротивления воздуха пропорциональной квадрату скорости, определить коэффициент сопротивления $k$. Действием силы тяжести пренебречь.",
  "figs": [],
