  "figs": [],
  "first": "Сосуд с жидкостью вращается с частотой n = 2 с⁻¹ вокруг вертикальной оси.",
  "answer": "$\\varphi = \\operatorname{arctg}(4\\pi^2 n^2 r/g) = 38°50'$.\n*Указание.* При равновесии жидкости равнодействующая всех сил, действующих на частицу жидкости, находящуюся на её поверхности, направлена по нормали к поверхности."
