  "md": "Молекула распадается на два атома. Масса одного из атомов в $n = 3$ раза больше, чем другого. Пренебрегая начальной кинетической энергией и импульсом молекулы, определить кинетические энергии $T_1$ и $T_2$ атомов, если их суммарная кинетическая энергия $T = 0{,}032$ нДж.",
