  "page": "47",
  "star": false,
  "md": "Пуля массой $m = 10$ г, летевшая со скоростью $v = 600$ м/с, попала в баллистический маятник (рис. 2.11) массой $M = 5$ кг и застряла в нём. На какую высоту $h$, откачнувшись после удара, поднялся маятник?",
  "figs": [
   "2.11"
  ],
  "first": "Пуля массой m = 10 г, летевшая со скоростью v = 600 м/с, попала в баллистический маятник (рис. 2.11) массой M = 5 кг и застряла в нём.",
