  "star": true,
  "md": "Два шара массами $m$ и $4m$ движутся в одном направлении, имея одинаковые кинетические энергии ($T_1 = T_2 = 100$ Дж). Определить непосредственно после удара: 1) кинетическую энергию $T'_2$ второго (бо́льшего) шара; 2) изменение $\\Delta U$ внутренней энергии шаров. Удар считать прямым, центральным, неупругим.",
  "figs": [],
  "first": "Два шара массами m и 4m движутся в одном направлении, имея одинаковые кинетические энергии (T1 = T2 = 100 Дж).",
