  "md": "Два шара массами $m$ и $4m$ движутся навстречу друг другу, имея одинаковые кинетические энергии ($T_1 = T_2 = 200$ Дж). Определить непосредственно после удара: 1) кинетическую энергию $T'_1$ первого (меньшего) шара; 2) изменение $\\Delta U$ внутренней энергии шаров. Удар считать центральным, неупругим.",
  "figs": [],
  "first": "Два шара массами m и 4m движутся навстречу друг другу, имея одинаковые кинетические энергии (T1 = T2 = 200 Дж).",
