  "page": "50",
  "star": true,
  "md": "Каково относительное изменение $\\dfrac{|\\Delta m|}{m_\\text{c}}$ массы ракеты ($m_\\text{c}$ — стартовая масса) к тому моменту времени, когда её скорость $v$ достигнет скорости $u$ истечения газов из сопла ракеты? Силами тяжести и сопротивления воздуха пренебречь.",
  "figs": [],
  "first": "Каково относительное изменение |Δ m|/mc массы ракеты (mc — стартовая масса) к тому моменту времени, когда её скорость v достигнет скорости…",
