  "page": "68",
  "star": false,
  "md": "Через блок, имеющий форму диска, перекинут шнур. К концам шнура привязали грузики массой $m_1 = 100$ г и $m_2 = 110$ г. С каким ускорением $a$ будут двигаться грузики, если масса $m$ блока равна 400 г? Трение при вращении блока ничтожно мало.",
