  "star": false,
  "md": "Маховик, имеющий вид диска радиусом $R = 40$ см и массой $m_1 = 48$ кг, может вращаться вокруг горизонтальной оси. К его цилиндрической поверхности прикреплён конец нерастяжимой нити, к другому концу которой подвешен груз массой $m_2 = 0{,}2$ кг (рис. 3.18). Груз был приподнят и затем опущен. Упав свободно с высоты $h = 2$ м, груз натянул нить и благодаря этому привёл маховик во вращение. Какую угловую скорость $\\omega$ груз сообщил при этом маховику?",
