  "page": "70",
  "star": false,
  "md": "На краю горизонтальной платформы, имеющей форму диска радиусом $R = 2$ м, стоит человек массой $m_1 = 80$ кг. Масса $m_2$ платформы равна 240 кг. Платформа может вращаться вокруг вертикальной оси, проходящей через её центр. Пренебрегая трением, найти, с какой угловой скоростью $\\omega$ будет вращаться платформа, если человек будет идти вдоль её края со скоростью $v = 2$ м/с относительно платформы.",
