  "md": "В центре скамьи Жуковского стоит человек и держит в руках стержень длиной $l = 2{,}4$ м и массой $m = 8$ кг, расположенный вертикально по оси вращения скамьи. Скамья с человеком вращается с частотой $n_1 = 1\\ \\text{с}^{-1}$. С какой частотой $n_2$ будет вращаться скамья с человеком, если он повернёт стержень в горизонтальное положение? Суммарный момент инерции $J$ человека и скамьи равен 6 кг·м².",
  "figs": [],
  "first": "В центре скамьи Жуковского стоит человек и держит в руках стержень длиной l = 2,4 м и массой m = 8 кг, расположенный вертикально по оси…",
