  "page": "72",
  "star": false,
  "md": "Однородный диск радиусом $R = 20$ см может свободно вращаться вокруг горизонтальной оси $z$, перпендикулярной плоскости диска и проходящей через точку $O$ (см. рис. 3.14). Определить угловую $\\omega$ и линейную $v$ скорости точки $B$ на диске в момент прохождения им положения равновесия. Вычисления выполнить для следующих случаев: 1) $a = b = R$, $\\alpha = \\pi/2$; 2) $a = R/2$, $b = 0$, $\\alpha = \\pi/3$; 3) $a = 2R/3$, $b = 2R/3$, $\\alpha = 5\\pi/6$; 4) $a = R/3$, $b = R$, $\\alpha = 2\\pi/3$.",
