  "star": true,
  "md": "Атом гелия налетает на покоящуюся молекулу азота со скоростью $v = 10^3$ м/с так, как это изображено на рис. 3.19 ($m_1$ — масса атома гелия, $m_2$ — масса атома азота). Определить непосредственно после столкновения: 1) скорость $u_1$, импульс $p'_1$ и изменение $\\Delta p_1$ импульса атома гелия; 2) скорость $v_C$ центра масс, импульс $p'_2$, угловую скорость $\\omega$ вращения и момент импульса $L_z$ молекулы азота относительно оси $z$, проходящей через её центр масс ($C$). Удар между атомами считать упругим. Атомы рассматривать как материальные точки, молекулу как жёсткий ротатор. Межъядерное расстояние $d = 0{,}109$ нм.",
