  "answer": "1) $u_1 = \\dfrac{m_1 - m_2}{m_1 + m_2}v_1 = -556$ м/с, $p'_1 = \\dfrac{m_1 - m_2}{m_1 + m_2}m_1 v_1 = -3{,}71\\times$\n$\\times\\,10^{-24}$ кг·м/с, $\\Delta p_1 = -\\dfrac{2m_2}{m_1 + m_2}m_1 v_1 = 1{,}04\\cdot 10^{-23}$ кг·м/с; 2) $v_C = \\dfrac{m_1}{m_1 + m_2}v_1 = 222$ м/с, $p'_2 = \\dfrac{2m_2}{m_1 + m_2}m_1 v_1 = 1{,}04\\cdot 10^{-23}$ кг·м/с, $\\omega = \\dfrac{2m_1}{m_1 + m_2}\\dfrac{v_1}{d} = 4{,}08\\cdot 10^{12}$ рад/с, $L_z = \\dfrac{m_1 m_2}{m_1 + m_2}v_1 d = 5{,}66\\cdot 10^{-34}$ кг·м²/с."
