  "page": "87",
  "star": false,
  "md": "Найти зависимость ускорения свободного падения $g$ от расстояния $r$, отсчитанного от центра планеты, плотность $\\rho$ которой можно считать для всех точек одинаковой. Построить график зависимости $g(r)$. Радиус $R$ планеты считать известным.",
