  "star": false,
  "md": "Ракета пущена с Земли с начальной скоростью $v_0 = 15$ км/с. К какому пределу будет стремиться скорость ракеты, если расстояние ракеты от Земли бесконечно увеличивается? Сопротивление воздуха и притяжение других небесных тел, кроме Земли, не учитывать.",
  "figs": [],
  "first": "Ракета пущена с Земли с начальной скоростью v0 = 15 км/с.",
  "answer": "$v = \\sqrt{v_0^2 - 2gR} = 10$ км/с."
