  "star": false,
  "md": "Комета огибает Солнце, двигаясь по орбите, которую можно считать параболической. С какой скоростью $v$ движется комета, когда она проходит через перигей (ближайшую к Солнцу точку своей орбиты), если расстояние $r$ кометы от Солнца в этот момент равно 50 Гм?",
  "figs": [],
