  "md": "К проволоке диаметром $d = 2$ мм подвешен груз массой $m = 1$ кг. Определить напряжение $\\sigma$, возникшее в проволоке.",
  "figs": [],
  "first": "К проволоке диаметром d = 2 мм подвешен груз массой m = 1 кг.",
