  "star": false,
  "md": "Какой наибольший груз может выдержать стальная проволока диаметром $d = 1$ мм, не выходя за предел упругости $\\sigma_\\text{упр} = 294$ МПа? Какую долю первоначальной длины составляет удлинение проволоки при этом грузе?",
  "figs": [],
  "first": "Какой наибольший груз может выдержать стальная проволока диаметром d = 1 мм, не выходя за предел упругости σупр = 294 МПа?",
