  "star": false,
  "md": "Свинцовая проволока подвешена в вертикальном положении за верхний конец. Какую наибольшую длину $l$ может иметь проволока, не обрываясь под действием силы тяжести? Предел прочности $\\sigma_\\text{пр}$ свинца равен 12,3 МПа.",
