  "md": "Гиря массой $m = 10$ кг, привязанная к проволоке, вращается с частотой $n = 2$ с⁻¹ вокруг вертикальной оси, проходящей через конец проволоки, скользя при этом без трения по горизонтальной поверхности. Длина $l$ проволоки равна 1,2 м, площадь $S$\nеё поперечного сечения равна 2 мм². Найти напряжение $\\sigma$ металла проволоки. Массой её пренебречь.",
  "figs": [],
  "first": "Гиря массой m = 10 кг, привязанная к проволоке, вращается с частотой n = 2 с⁻¹ вокруг вертикальной оси, проходящей через конец проволоки,…",
