  "page": "101",
  "star": false,
  "md": "Импульс $p$ релятивистской частицы равен $m_0c$. Под действием внешней силы импульс частицы увеличился в два раза. Во сколько раз возрастёт при этом энергия частицы: 1) кинетическая? 2) полная?",
