  "star": false,
  "md": "Точка совершает колебания по закону $x = A\\sin\\omega t$. В некоторый момент времени смещение $x_1$ точки оказалось равным 5 см. Когда фаза колебаний увеличилась вдвое, смещение $x_2$ стало равным 8 см. Найти амплитуду $A$ колебаний.",
  "figs": [],
