  "md": "Точка участвует одновременно в двух взаимно перпендикулярных колебаниях, выражаемых уравнениями $x = A_1\\cos\\omega t$ и $y = A_2\\sin 0{,}5\\omega t$, где $A_1 = 2$ см, $A_2 = 3$ см. Найти уравнение траектории точки и построить её, указав направление движения.",
  "figs": [],
  "first": "Точка участвует одновременно в двух взаимно перпендикулярных колебаниях, выражаемых уравнениями x = A1ω t и y = A2 0,5ω t, где A1 = 2 см,…",
