  "star": false,
  "md": "Имеются два источника, совершающие колебания в одинаковой фазе и возбуждающие в окружающей среде плоские волны одинаковой частоты и амплитуды ($A_1 = A_2 = 1$ мм). Найти амплитуду $A$ колебаний точки среды, отстоящей от одного источника колебаний на расстоянии $x_1 = 3{,}5$ м и от другого — на $x_2 = 5{,}4$ м. Направления колебаний в рассматриваемой точке совпадают. Длина волны $\\lambda = 0{,}6$ м.",
