  "page": "128–129",
  "star": false,
  "md": "Широкая трубка, закрытая снизу и расположенная вертикально, наполнена до краёв водой. Над верхним отверстием трубки помещён звучащий камертон, частота $\\nu$ колебаний которого равна\n440 Гц. Через кран, находящийся внизу, воду медленно выпускают. Когда уровень воды в трубке понижается на $\\Delta H = 19{,}5$ см, звук камертона усиливается. Определить скорость $c_\\text{зв}$ звука в условиях опыта.",
