  "md": "Одна треть молекул азота массой $m = 10$ г распалась на атомы. Определить полное число $N$ частиц, находящихся в газе.",
  "figs": [],
  "first": "Одна треть молекул азота массой m = 10 г распалась на атомы.",
  "answer": "$N = \\dfrac{4}{3}\\dfrac{m}{M}N_\\text{A} = 2{,}87\\cdot 10^{20}$ частиц."
