  "md": "В цилиндр длиной $l = 1{,}6$ м, заполненный воздухом при нормальном атмосферном давлении $p_0$, начали медленно вдвигать поршень площадью $S = 200$ см². Определить силу $F$, которая будет действовать на поршень, если его остановить на расстоянии $l_1 = 10$ см от дна цилиндра.",
  "figs": [],
  "first": "В цилиндр длиной l = 1,6 м, заполненный воздухом при нормальном атмосферном давлении p0, начали медленно вдвигать поршень площадью S = 200…",
