  "page": "138",
  "star": false,
  "md": "Колба вместимостью $V = 300$ см², закрытая пробкой с краном, содержит разреженный воздух. Для измерения давления в колбе горлышко колбы погрузили в воду на незначительную глубину и открыли кран, в результате чего в колбу вошла вода массой $m = 292$ г. Определить первоначальное давление $p$ в колбе, если атмосферное давление $p_0 = 100$ кПа. *(так напечатано: «300 см²»; по смыслу вместимость — 300 см³)*",
  "figs": [],
  "first": "Колба вместимостью V = 300 см², закрытая пробкой с краном, содержит разреженный воздух.",
