  "page": "163",
  "star": false,
  "md": "Цилиндр радиусом $R_1 = 10$ см и длиной $l = 30$ см расположен внутри цилиндра радиусом $R_2 = 10{,}5$ см так, что оси обоих цилиндров совпадают. Малый цилиндр неподвижен, большой вращается относительно геометрической оси с частотой $n = 15\\ \\text{с}^{-1}$. Динамическая вязкость $\\eta$ газа, в котором находятся цилиндры, равна 8,5 мкПа·с. Определить вращающий момент $M$, действующий на поверхность внутреннего цилиндра.",
