  "star": false,
  "md": "В ультраразрежённом азоте, находящемся под давлением $p = 1$ мПа и при температуре $T = 300$ К, движутся друг относительно друга две параллельные пластины со скоростью $u = 1$ м/с. Расстояние между пластинами не изменяется и много меньше средней длины свободного пробега молекул. Определить силу $F$ внутреннего трения, действующую на поверхность пластин площадью $S = 1$ м².",
