  "star": false,
  "md": "При какой температуре $T$ находится оксид азота, если его объём $V$ и давление $p$ в $k = 3$ раза превышают соответствующие критические значения $V_\\text{кр}$ и $p_\\text{кр}$? Критическая температура $T_\\text{кр}$ оксида азота равна 180 К.",
