  "page": "199",
  "star": false,
  "md": "В горизонтально расположенной трубе с площадью $S_1$ поперечного сечения, равной 20 см², течёт жидкость. В одном месте труба имеет сужение, в котором площадь $S_2$ сечения равна 12 см². Разность $\\Delta h$ уровней в двух манометрических трубках, установленных в широкой и узкой частях трубы, равна 8 см. Определить объёмный расход $Q_V$ жидкости.",
  "figs": [],
