  "md": "Струя воды диаметром $d = 2$ см, движущаяся со скоростью $v = 10$ м/с, ударяется о неподвижную плоскую поверхность, поставленную перпендикулярно струе. Найти силу $F$ давления струи на поверхность, считая, что после удара о поверхность скорость частиц воды равна нулю.",
