  "star": false,
  "md": "Даны два шарика массой $m = 1$ г каждый. Какой заряд $Q$ нужно сообщить каждому шарику, чтобы сила взаимного отталкивания зарядов уравновесила силу взаимного притяжения шариков по закону тяготения Ньютона? Рассматривать шарики как материальные точки.",
  "figs": [],
  "first": "Даны два шарика массой m = 1 г каждый.",
