  "star": false,
  "md": "В элементарной теории атома водорода принимают, что электрон обращается вокруг ядра по круговой орбите. Определить\nскорость $v$ электрона, если радиус орбиты $r = 53$ пм, а также частоту $n$ вращения электрона.",
