  "answer": "$v = \\dfrac{|e|}{\\sqrt{4\\pi\\varepsilon_0mr}} = 2{,}19\\cdot 10^6$ м/с; $n = v/(2\\pi r) = 6{,}58\\cdot 10^{15}$ с⁻¹ ($m$ — масса электрона; $e$ — его заряд)."
