  "star": false,
  "md": "Большая металлическая пластина несёт равномерно распределённый по поверхности заряд ($\\sigma = 10$ нКл/м²). На малом расстоянии от пластины находится точечный заряд $Q = 100$ нКл. Найти силу $F$, действующую на заряд.",
