  "star": false,
  "md": "Металлический шар имеет заряд $Q_1 = 100$ нКл. На расстоянии, равном радиусу шара, от его поверхности находится конец нити, вытянутой вдоль силовой линии. Нить несёт равномерно распределённый по длине заряд $Q_2 = 10$ нКл. Длина нити равна радиусу шара. Определить силу $F$, действующую на нить, если радиус $R$ шара равен 10 см.",
  "figs": [],
  "first": "Металлический шар имеет заряд Q1 = 100 нКл.",
