  "page": "227",
  "star": false,
  "md": "В вершине конуса с телесным углом $\\Omega = 0{,}5$ ср находится точечный заряд $Q = 30$ нКл. Вычислить поток $\\Psi$ электрического смещения через площадку, ограниченную линией пересечения поверхности конуса с любой другой поверхностью.",
