  "star": false,
  "md": "Заряд $Q = 1$ мкКл равноудалён от краёв круглой площадки на расстояние $r = 20$ см. Радиус $R$ площадки равен 12 см. Определить среднее значение нормальной составляющей напряжённости $\\langle E_n\\rangle$ в пределах площадки.",
