  "star": false,
  "md": "Электрическое поле создано бесконечной прямой равномерно заряженной линией ($\\tau = 300$ нКл/м). Определить поток $\\Psi$ электрического смещения через прямоугольную площадку, две большие стороны которой параллельны заряженной линии и одинаково удалены от неё на расстояние $r = 20$ см. Стороны площадки имеют размеры $a = 20$ см, $b = 40$ см.",
